    public CompletableFuture<Object> loadPositionsSnapshot(Client client, String messageHash)
    {
        return BaseExchange.supplyAsync(() -> this.loadPositionsSnapshotCore(client, messageHash));
    }

    private Void loadPositionsSnapshotCore(Client client, String messageHash)
    {

        // as only one ws channel gives positions for all types, for snapshot must load all positions
        List<CompletableFuture<?>> fetchFunctions = new ArrayList<CompletableFuture<?>>(Arrays.<CompletableFuture<?>>asList(this.fetchPositions((List<String>) null, new HashMap<String, Object>() {{}})));
        List<Object> promises = (CompletableFuture.allOf(fetchFunctions.toArray(new CompletableFuture<?>[0])).thenApply((promiseAllDone) -> new ArrayList<Object>(fetchFunctions.stream().<Object>map(CompletableFuture::join).toList()))).join();
        this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
        io.github.ccxt.ws.ArrayCache cache = (io.github.ccxt.ws.ArrayCache) this.positions;
        for (var i = 0; i < promises.size(); i++)
        {
            List<?> positions = (List<?>) (promises == null || i < 0 || i >= promises.size() ? null : promises.get(i));
            for (var ii = 0; ii < positions.size(); ii++)
            {
                cache.append((positions == null || ii < 0 || ii >= positions.size() ? null : positions.get(ii)));
            }
        }
        // don't remove the future from the .futures cache
        if (client.futures.containsKey(messageHash))
        {
            io.github.ccxt.ws.Future future = (client.futures == null || messageHash == null ? null : client.futures.get(messageHash));
            future.resolve(cache);
            client.resolve(cache, "positions");
        }
        return null;

    }

    public void handlePositions(Client client, Object lists)
    {
        //
        // [
        //     {
        //         "symbol":"ETH-USDT",
        //         "exitPrice":"0",
        //         "side":"LONG",
        //         "maxSize":"2820.000",
        //         "sumOpen":"1.820",
        //         "sumClose":"0.000",
        //         "netFunding":"0.000000",
        //         "entryPrice":"2500.000000000000000000",
        //         "accountId":"1024000",
        //         "createdAt":1652179377769,
        //         "size":"1.820",
        //         "realizedPnl":"0",
        //         "closedAt":1652185521392,
        //         "updatedAt":1652185521392
        //     }
        // ]
        //
        // each account is connected to a different endpoint
        // and has exactly one subscriptionhash which is the account type
        if (java.util.Objects.equals(this.positions, null))
        {
            this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
        }
        io.github.ccxt.ws.ArrayCache cache = (io.github.ccxt.ws.ArrayCache) this.positions;
        List<Object> newPositions = new ArrayList<Object>(Arrays.asList());
        for (var i = 0; i < ((List<?>)lists).size(); i++)
        {
            Map<String, Object> position = (Map<String, Object>) this.parsePosition(this.safeDict(lists, i, new HashMap<String, Object>() {{}}), (Map<String, Object>) null);
            String side = this.safeString(position, "side");
            // hacky solution to handle closing positions
            // without crashing, we should handle this properly later
            ((List<Object>)newPositions).add(position);
            if (java.util.Objects.equals(side, null) || java.util.Objects.equals(side, ""))
            {
                // closing update, adding both sides to "reset" both sides
                // since we don't know which side is being closed
                position.put("side", "long");
                cache.append(position);
                position.put("side", "short");
                cache.append(position);
                position.put("side", null);
            } else
            {
                // regular update
                cache.append(position);
            }
        }
        List<Object> messageHashes = this.findMessageHashes(client, "positions::");
        for (var i = 0; i < messageHashes.size(); i++)
        {
            String messageHash = (String) (messageHashes == null || i < 0 || i >= messageHashes.size() ? null : messageHashes.get(i));
            List<Object> parts = new ArrayList<Object>(Arrays.asList(messageHash.split(java.util.regex.Pattern.quote("::"))));
            String symbolsString = this.safeString(parts, 1, "");
            List<Object> symbols = new ArrayList<Object>(Arrays.asList(((String)symbolsString).split(java.util.regex.Pattern.quote(","))));
            List<Object> positions = (List<Object>) this.filterByArray(newPositions, "symbol", symbols, false);
            if (!this.isEmpty(positions))
            {
                client.resolve(positions, messageHash);
            }
        }
        client.resolve(newPositions, "positions");
    }

