    private Object authenticateCore(String url, Map<String, Object> parameters)
    {

        this.checkRequiredCredentials(true);
        String timestamp = String.valueOf(this.milliseconds());
        String request_path = "/ws/accounts";
        String http_method = "GET";
        String messageString = (((timestamp + http_method) + request_path));
        String signature = this.hmac(this.encode(messageString), this.encode(this.stringToBase64(this.secret)), sha256(), "base64");
        String messageHash = "authenticated";
        Client client = this.client(url);
        io.github.ccxt.ws.Future future = client.reusableFuture(messageHash);
        boolean authenticated = (this.safeValue(client.subscriptions, messageHash)) != null;
        if (!authenticated)
        {
            // auth sign
            Map<String, Object> message = new HashMap<String, Object>();
            message.put("op", "login");
            HashMap<String, Object> mapLiteral1 = new HashMap<String, Object>();
            mapLiteral1.put("type", "login");
            mapLiteral1.put("topics", new ArrayList<Object>(Arrays.asList("ws_zk_accounts_v3")));
            mapLiteral1.put("httpMethod", http_method);
            mapLiteral1.put("requestPath", request_path);
            mapLiteral1.put("apiKey", this.apiKey);
            mapLiteral1.put("passphrase", this.password);
            mapLiteral1.put("timestamp", timestamp);
            mapLiteral1.put("signature", signature);
            message.put("args", new ArrayList<Object>(Arrays.asList(Helpers.json(mapLiteral1))));
            this.watch(url, messageHash, message, messageHash, null);
        }
        return future.getFuture().join();

    }

    public Boolean handleErrorMessage(Client client, Map<String, Object> message)
    {
        //
        //   {
        //       "success": false,
        //       "ret_msg": "error:invalid op",
        //       "conn_id": "5e079fdd-9c7f-404d-9dbf-969d650838b5",
        //       "request": { op: '', args: null }
        //   }
        //
        // auth error
        //
        //   {
        //       "success": false,
        //       "ret_msg": "error:USVC1111",
        //       "conn_id": "e73770fb-a0dc-45bd-8028-140e20958090",
        //       "request": {
        //         "op": "auth",
        //         "args": [
        //           "9rFT6uR4uz9Imkw4Wx",
        //           "1653405853543",
        //           "542e71bd85597b4db0290f0ce2d13ed1fd4bb5df3188716c1e9cc69a879f7889"
        //         ]
        //   }
        //
        //   { code: '-10009', desc: "Invalid period!" }
        //
        //   {
        //       "reqId":"1",
        //       "retCode":170131,
        //       "retMsg":"Insufficient balance.",
        //       "op":"order.create",
        //       "data":{
        //
        //       },
        //       "header":{
        //           "X-Bapi-Limit":"20",
        //           "X-Bapi-Limit-Status":"19",
        //           "X-Bapi-Limit-Reset-Timestamp":"1714236608944",
        //           "Traceid":"3d7168a137bf32a947b7e5e6a575ac7f",
        //           "Timenow":"1714236608946"
        //       },
        //       "connId":"cojifin88smerbj9t560-406"
        //   }
        //
        String code = this.safeStringN(message, new ArrayList<Object>(Arrays.asList("code", "ret_code", "retCode")));
        try
        {
            if (!java.util.Objects.equals(code, null) && !java.util.Objects.equals(code, "0"))
            {
                String feedback = ((this.id + " ") + this.json(message));
                this.throwExactlyMatchedException((Map<String, Object>) (this.exceptions.get("exact")), (String) (code), feedback);
                String msg = this.safeString2(message, "retMsg", "ret_msg");
                this.throwBroadlyMatchedException((Map<String, Object>) (this.exceptions.get("broad")), (String) (msg), feedback);
                throw new ExchangeError(feedback) ;
            }
            Boolean success = (Boolean) this.safeBool(message, "success", (Object) null);
            if ((!java.util.Objects.equals(success, null)) && (!Boolean.TRUE.equals(success)))
            {
                String ret_msg = this.safeString(message, "ret_msg", "");
                Map<String, Object> request = this.safeDict(message, "request", new HashMap<String, Object>() {{}});
                String op = this.safeString(request, "op");
                // Benign re-subscribe notice (same shape as bitmart 90008 /
                // krakenfutures "Already subscribed"): the original subscription
                // is still active and delivering data on this socket. Without
                // this short-circuit the catch-clause's `client.reject(error,
                // messageHash)` rejects every in-flight future on the connection
                // because apex doesn't echo a `reqId` on these warnings.
                if (!java.util.Objects.equals(ret_msg, null) && ((String)ret_msg).indexOf("already subscribed") >= 0)
                {
                    return false;
                }
                if (java.util.Objects.equals(op, "auth"))
                {
                    throw new AuthenticationError(("Authentication failed: " + ret_msg)) ;
                } else
                {
                    throw new ExchangeError(((this.id + " ") + ret_msg)) ;
                }
            }
            return false;
        } catch(Exception error)
        {
            if ((error instanceof AuthenticationError))
            {
                String messageHash = "authenticated";
                client.reject(error, messageHash);
                if (client.subscriptions.containsKey(messageHash))
                {
                    client.subscriptions.remove(messageHash);
                }
            } else
            {
                String messageHash = this.safeString(message, "reqId");
                client.reject(error, messageHash);
            }
            return true;
        }
    }

    public void handleMessage(Client client, Map<String, Object> message)
    {
        if (java.util.Objects.equals(this.handleErrorMessage(client, message), true))
        {
            return;
        }
        String ret_msg = this.safeString(message, "ret_msg");
        Long pong = this.safeInteger(message, "pong");
        if (java.util.Objects.equals(ret_msg, "pong") || !java.util.Objects.equals(pong, null))
        {
            this.handlePong(client, message);
            return;
        }
        String topic = this.safeString2(message, "topic", "op", "");
        Map<String, String> methods = new HashMap<String, String>() {{
            put("ws_zk_accounts_v3", "handleAccount");
            put("orderBook", "handleOrderBook");
            put("depth", "handleOrderBook");
            put("candle", "handleOHLCV");
            put("kline", "handleOHLCV");
            put("ticker", "handleTicker");
            put("instrumentInfo", "handleTicker");
            put("trade", "handleTrades");
            put("recentlyTrade", "handleTrades");
            put("pong", "handlePong");
            put("auth", "handleAuthenticate");
            put("ping", "handlePing");
        }};
        String exacMethod = methods.get(topic);
        if (!java.util.Objects.equals(exacMethod, null))
        {
            switch (exacMethod) {
                case "handleAccount":
                    this.handleAccount(client, message);
                    break;
                case "handleOrderBook":
                    this.handleOrderBook(client, message);
                    break;
                case "handleOHLCV":
                    this.handleOHLCV(client, message);
                    break;
                case "handleTicker":
                    this.handleTicker(client, message);
                    break;
                case "handleTrades":
                    this.handleTrades(client, message);
                    break;
                case "handlePong":
                    this.handlePong(client, message);
                    break;
                case "handleAuthenticate":
                    this.handleAuthenticate(client, message);
                    break;
                case "handlePing":
                    this.handlePing(client, message);
                    break;
                default:
                    throw new RuntimeException("Method not found: " + exacMethod);
            }
            return;
        }
        List<String> keys = new ArrayList<String>(methods.keySet());
        for (var i = 0; i < keys.size(); i++)
        {
            String key = (keys == null || i < 0 || i >= keys.size() ? null : keys.get(i));
            if ((topic == null || keys == null || i < 0 || i >= keys.size() || keys.get(i) == null ? -1 : topic.indexOf(keys.get(i))) >= 0)
            {
                String method = methods.get(key);
                switch (method) {
                    case "handleAccount":
                        this.handleAccount(client, message);
                        break;
                    case "handleOrderBook":
                        this.handleOrderBook(client, message);
                        break;
                    case "handleOHLCV":
                        this.handleOHLCV(client, message);
                        break;
                    case "handleTicker":
                        this.handleTicker(client, message);
                        break;
                    case "handleTrades":
                        this.handleTrades(client, message);
                        break;
                    case "handlePong":
                        this.handlePong(client, message);
                        break;
                    case "handleAuthenticate":
                        this.handleAuthenticate(client, message);
                        break;
                    case "handlePing":
                        this.handlePing(client, message);
                        break;
                    default:
                        throw new RuntimeException("Method not found: " + method);
                }
                return;
            }
        }
        // unified auth acknowledgement
        String type = this.safeString(message, "type");
        if (java.util.Objects.equals(type, "AUTH_RESP"))
        {
            this.handleAuthenticate(client, message);
        }
    }

    public Object ping(Client client)
    {
        Long timeStamp = this.milliseconds();
        client.lastPong = ((Number)timeStamp).longValue();
        return new HashMap<String, Object>() {{
            put( "args", new ArrayList<Object>(Arrays.asList(String.valueOf(timeStamp))) );
            put( "op", "ping" );
        }};
    }

    public CompletableFuture<Object> pong(Client client, Map<String, Object> message)
    {
        return BaseExchange.supplyAsync(() -> this.pongCore(client, message));
    }

    private Void pongCore(Client client, Map<String, Object> message)
    {

        //
        //     {"op": "ping", "args": ["1761069137485"]}
        //
        Long timeStamp = this.milliseconds();
        try
        {
            (client.send(new HashMap<String, Object>() {{
                put( "args", new ArrayList<Object>(Arrays.asList(String.valueOf(timeStamp))) );
                put( "op", "pong" );
            }})).join();
        } catch(Exception e)
        {
            var error = new NetworkError(((this.id + " handlePing failed with error ") + this.exceptionMessage(e, true)));
            client.reset(error);
        }
        return null;

    }

    public Map<String, Object> handlePong(Client client, Map<String, Object> message)
    {
        //
        //   {
        //       "success": true,
        //       "ret_msg": "pong",
        //       "conn_id": "db3158a0-8960-44b9-a9de-ac350ee13158",
        //       "request": { op: "ping", args: null }
        //   }
        //
        //   { pong: 1653296711335 }
        //
        client.lastPong = ((Number)this.safeInteger(message, "pong", this.milliseconds())).longValue();
        return message;
    }

    public void handlePing(Client client, Map<String, Object> message)
    {
        client.lastPong = ((Number)this.milliseconds()).longValue();
        this.pong(client, message);
    }

